list=result.match(/href="([^"]+)">(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)<[\s\S]*?font>(.*?)</g);
arr=[];
number =Number(baseUrl.match(/pages=(\d+)/)[1]); number = 200*(number-1);
for(i in list){
